/**
 * The pure quest level + question builder.
 *
 * The fixture (tests/unit/lib/fixtures/quest-tier1.json) is a snapshot of the
 * real tier-1 facts, generated by scripts/verify-quest-numbers.mjs
 * --emit-tier1-fixture. It pins the spec's §6.1 payload byte-for-byte without
 * needing a database.
 */
import { describe, expect, it } from 'vitest';
import {
  buildLevel,
  buildTier,
  firstFreeClause,
  plainSyllable,
  toneFormsOf,
} from '@/lib/game-quest';
import type {
  QuestCharFact,
  QuestLevelPayload,
  QuestQuestion,
  QuestTier,
} from '@/lib/game-quest-types';
import tier1 from './fixtures/quest-tier1.json';

const facts = tier1.facts as QuestCharFact[];
const tier: QuestTier = buildTier(tier1.tier, facts);

/** Every level of the tier as an API payload (no nulls — the tier is valid). */
const payloads: QuestLevelPayload[] = tier.levels
  .map((_, index) => buildLevel(tier, index + 1))
  .filter((payload): payload is QuestLevelPayload => payload !== null);

/** The payload of one char, looked up by its character. */
function payloadOf(char: string): QuestLevelPayload {
  const found = payloads.find((p) => p.chars.some((c) => c.char === char));
  if (!found) throw new Error(`char ${char} is not in the tier-1 ladder`);
  return found;
}

/** One char's payload, looked up by its character. */
function charOf(char: string) {
  const found = payloadOf(char).chars.find((c) => c.char === char);
  if (!found) throw new Error(`char ${char} is not in the tier-1 ladder`);
  return found;
}

/** How many pairs of chars in this list share a plain syllable? */
function sameSyllablePairs(list: QuestCharFact[]): number {
  const counts = new Map<string, number>();
  for (const f of list) {
    const key = plainSyllable(f.reading);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  let pairs = 0;
  for (const n of counts.values()) pairs += (n * (n - 1)) / 2;
  return pairs;
}

/** Do the two clauses share any 2-character substring? */
function shares2(a: string, b: string): boolean {
  for (let i = 0; i + 2 <= a.length; i++) if (b.includes(a.slice(i, i + 2))) return true;
  return false;
}

/** The radical distractors, ordered by their code-point distance from the correct one. */
function radicalDistractors(question: QuestQuestion, correct: string): string[] {
  const options = question.options.filter((_, i) => i !== question.answerIndex);
  return options.sort(
    (a, b) =>
      Math.abs(a.codePointAt(0)! - correct.codePointAt(0)!) -
      Math.abs(b.codePointAt(0)! - correct.codePointAt(0)!),
  );
}

describe('buildTier', () => {
  it('the sweep order is syllable-alphabetical', () => {
    const level1 = tier.levels[0];
    expect(level1.map((f) => f.char)).toEqual(['爱', '八', '杯', '本', '不']);
    expect(level1.map((f) => plainSyllable(f.reading))).toEqual([
      'ai',
      'ba',
      'bei',
      'ben',
      'bu',
    ]);
  });

  it('the same-syllable pairs stay near zero', () => {
    for (const level of tier.levels) {
      expect(sameSyllablePairs(level)).toBeLessThanOrEqual(1);
    }
    // The 21 pairs of the whole ladder sit in tiers 3-6; tier 1 has none.
    expect(tier.levels.reduce((acc, l) => acc + sameSyllablePairs(l), 0)).toBe(0);
  });

  it('every full level has at least 3 distinct radicals', () => {
    const full = tier.levels.filter((l) => l.length === 5);
    expect(full).toHaveLength(30);
    for (const level of full) {
      expect(new Set(level.map((f) => f.radical)).size).toBeGreaterThanOrEqual(3);
    }
  });

  it('the short tail level is legal and reports its own size', () => {
    const tail = buildLevel(tier, 31);
    expect(tail).not.toBeNull();
    expect(tail?.chars).toHaveLength(2);
    expect(tail?.levelCount).toBe(31);
    expect(tail?.level).toBe(31);
  });

  it('the eligible pool size', () => {
    expect(tier.levels.flat().length).toBe(152);
    expect(tier.skipped).toBe(26);
    expect(tier.tierSize).toBe(178);
  });

  it('the level count', () => {
    expect(tier.levels).toHaveLength(31);
  });
});

describe('the questions', () => {
  it('读音 distractors never equal the correct plain syllable', () => {
    for (const payload of payloads) {
      for (const c of payload.chars) {
        const q = c.questions.find((x) => x.kind === 'pinyin');
        expect(q).toBeDefined();
        expect(q?.options.filter((o) => o === c.plainPinyin)).toHaveLength(1);
        expect(q?.options[q?.answerIndex ?? -1]).toBe(c.plainPinyin);
      }
    }
  });

  it('读音 distractors never equal a pinyin_alt plain form', () => {
    // 不's alternates are bù / bú / fǒu / fōu / pī → the plain forms
    // bu / bu / fou / fou / pi. 'bu' is the correct answer itself, so the
    // rule can only bite on the distractors.
    const bu = charOf('不');
    const q = bu.questions.find((x) => x.kind === 'pinyin');
    expect(q).toBeDefined();
    expect(q?.options[q?.answerIndex ?? -1]).toBe('bu');
    const distractors = (q?.options ?? []).filter((_, i) => i !== q?.answerIndex);
    for (const alt of ['bu', 'fou', 'pi']) expect(distractors).not.toContain(alt);
    // The brief lists the stripped alternatives as bu / fo / pi.
    for (const alt of ['bu', 'fo', 'pi']) expect(distractors).not.toContain(alt);
  });

  it('读音 distractors never equal a pinyin_alt plain form, for every char', () => {
    // The generalised rule: survivesPinyinFilters (lib/game-quest.ts) rejects
    // any candidate whose plain form equals the plain form of one of the
    // char's own alternates. Every eligible char must obey it — not just 不.
    const factOf = new Map(facts.map((f) => [f.char, f]));
    let checked = 0;
    for (const payload of payloads) {
      for (const c of payload.chars) {
        const fact = factOf.get(c.char);
        expect(fact).toBeDefined();
        const altPlainForms = (fact?.pinyinAlt ?? []).map((alt) => plainSyllable(alt));
        const q = c.questions.find((x) => x.kind === 'pinyin');
        expect(q).toBeDefined();
        const distractors = (q?.options ?? []).filter((_, i) => i !== q?.answerIndex);
        for (const alt of altPlainForms) {
          expect(distractors).not.toContain(alt);
        }
        checked++;
      }
    }
    // The whole eligible pool of tier 1 — 152 chars — was checked.
    expect(checked).toBe(152);
  });

  it('the 零声母 rule keeps "er" out of 爱\'s distractors', () => {
    const ai = charOf('爱');
    const q = ai.questions.find((x) => x.kind === 'pinyin');
    expect(q).toBeDefined();
    const distractors = (q?.options ?? [])
      .filter((_, i) => i !== q?.answerIndex)
      .sort();
    expect(distractors).toEqual(['cai', 'kai', 'lai']);
    expect(q?.options).not.toContain('er');
  });

  it('声调 options are the 4 tone forms of the syllable', () => {
    expect(toneFormsOf('爱')).toEqual(['āi', 'ái', 'ǎi', 'ài']);
    const q = charOf('爱').questions.find((x) => x.kind === 'tone');
    expect(q).toBeDefined();
    expect(q?.options).toHaveLength(4);
    expect(new Set(q?.options)).toEqual(new Set(['āi', 'ái', 'ǎi', 'ài']));
    expect(q?.options[q?.answerIndex ?? -1]).toBe('ài');
  });

  it('the tone-form vectors', () => {
    expect(toneFormsOf('春')).toEqual(['chūn', 'chún', 'chǔn', 'chùn']);
    expect(toneFormsOf('妈')).toEqual(['mā', 'má', 'mǎ', 'mà']);
    expect(toneFormsOf('绿')).toEqual(['lǖ', 'lǘ', 'lǚ', 'lǜ']);
    expect(toneFormsOf('略')).toEqual(['lüē', 'lüé', 'lüě', 'lüè']);
    expect(toneFormsOf('归')).toEqual(['guī', 'guí', 'guǐ', 'guì']);
    expect(toneFormsOf('爱')).toEqual(['āi', 'ái', 'ǎi', 'ài']);
    expect(toneFormsOf('长')).toEqual(['chāng', 'cháng', 'chǎng', 'chàng']);
  });

  it('a j/q/x/y syllable spells its ü as u', () => {
    // pinyin-pro's `pattern: 'final'` restores the ü (学 → final üè), but
    // the standard orthography writes it as u (xué). Without the correction
    // the four forms would be xüē xüé xüě xuè — and the char's own reading
    // would not be among them.
    expect(toneFormsOf('去')).toEqual(['qū', 'qú', 'qǔ', 'qù']);
    expect(toneFormsOf('学')).toEqual(['xuē', 'xué', 'xuě', 'xuè']);
    expect(toneFormsOf('觉')).toEqual(['juē', 'jué', 'juě', 'juè']);
    expect(toneFormsOf('雪')).toEqual(['xuē', 'xué', 'xuě', 'xuè']);
    expect(toneFormsOf('军')).toEqual(['jūn', 'jún', 'jǔn', 'jùn']);
    expect(toneFormsOf('需')).toEqual(['xū', 'xú', 'xǔ', 'xù']);
    expect(toneFormsOf('全')).toEqual(['quān', 'quán', 'quǎn', 'quàn']);
    // A ü after l / n keeps its umlaut.
    expect(toneFormsOf('女')).toEqual(['nǖ', 'nǘ', 'nǚ', 'nǜ']);
    expect(toneFormsOf('月')).toEqual(['yuē', 'yué', 'yuě', 'yuè']);
  });

  it('every fixture char\'s reading is among its four tone forms', () => {
    // The property that makes the whole ü class of bug impossible to
    // reintroduce silently: whenever toneFormsOf returns forms, the char's
    // own reading must be one of them — otherwise the ② question has no
    // correct answer.
    let checked = 0;
    for (const fact of facts) {
      const forms = toneFormsOf(fact.char);
      if (!forms) continue;
      expect(forms).toContain(fact.reading);
      checked++;
    }
    expect(checked).toBeGreaterThan(0);
  });

  it('a 轻声 char has no tone forms', () => {
    expect(toneFormsOf('的')).toBeNull();
    // 嗯 carries the syllabic nasal ǹ, which is deliberately not a tone mark.
    expect(toneFormsOf('嗯')).toBeNull();
  });

  it('部首 distractors are the nearest code points of the tier radical vocabulary', () => {
    const aiRadical = charOf('爱').questions.find((x) => x.kind === 'radical');
    expect(aiRadical).toBeDefined();
    expect(aiRadical?.options[aiRadical?.answerIndex ?? -1]).toBe('爪');
    expect(radicalDistractors(aiRadical!, '爪')).toEqual(['父', '犬', '玉']);

    // 本 is the tier-1 char whose radical is 木 (U+6728).
    const benRadical = charOf('本').questions.find((x) => x.kind === 'radical');
    expect(benRadical?.options[benRadical?.answerIndex ?? -1]).toBe('木');
    expect(radicalDistractors(benRadical!, '木')).toEqual(['月', '日', '欠']);
    expect(tier.radicals).not.toContain('斤');
  });

  it('词义: the correct option is the first free clause of at least 2 chars', () => {
    const q = charOf('爱').questions.find((x) => x.kind === 'meaning');
    expect(q).toBeDefined();
    const correct = q?.options[q?.answerIndex ?? -1] ?? '';
    expect(correct).toBe('对人和事物有深厚真挚的感情');
    expect(correct.length).toBeGreaterThanOrEqual(2);

    // 视's first free clause is the 1-char '看', so it never reaches the pool.
    const shi = facts.find((f) => f.char === '视');
    expect(shi).toBeDefined();
    expect(firstFreeClause(shi?.meaningZh ?? '', '视')).toBe('看');
    expect(tier.levels.flat().some((f) => f.char === '视')).toBe(false);
  });

  it('词义 distractors share no 2-character substring with the correct clause', () => {
    for (const payload of payloads) {
      for (const c of payload.chars) {
        const q = c.questions.find((x) => x.kind === 'meaning');
        expect(q).toBeDefined();
        const correct = q?.options[q?.answerIndex ?? -1] ?? '';
        for (const [i, option] of (q?.options ?? []).entries()) {
          if (i === q?.answerIndex) continue;
          expect(option).not.toContain(c.char);
          expect(shares2(correct, option)).toBe(false);
        }
      }
    }
  });
});

describe('buildLevel', () => {
  it('the §6.1 payload is a fixture', () => {
    const payload = buildLevel(tier, 1);
    expect(payload).not.toBeNull();
    const ai = payload?.chars.find((c) => c.char === '爱');
    expect(ai).toBeDefined();
    const questions = ai?.questions ?? [];
    expect(questions[0]).toEqual({
      kind: 'pinyin',
      options: ['cai', 'ai', 'kai', 'lai'],
      answerIndex: 1,
    });
    expect(questions[1]).toEqual({
      kind: 'tone',
      options: ['ài', 'ái', 'āi', 'ǎi'],
      answerIndex: 0,
    });
    expect(questions[2]).toEqual({
      kind: 'radical',
      options: ['父', '爪', '玉', '犬'],
      answerIndex: 1,
    });
    expect(questions[3]).toEqual({
      kind: 'meaning',
      options: [
        '被邀请或主动前来探访的人',
        '对人和事物有深厚真挚的感情',
        '光线强',
        '数量大',
      ],
      answerIndex: 1,
    });
  });

  it('is deterministic', () => {
    const first = buildLevel(tier, 1);
    const second = buildLevel(tier, 1);
    expect(JSON.stringify(first)).toBe(JSON.stringify(second));
    expect(JSON.stringify(buildLevel(tier, 1))).not.toBe(JSON.stringify(buildLevel(tier, 2)));
  });

  it('returns null for an out-of-range level', () => {
    expect(buildLevel(tier, 0)).toBeNull();
    expect(buildLevel(tier, 32)).toBeNull();
  });
});

describe('the tone answer guard', () => {
  it('throws when a char\'s reading is not one of its four tone forms', () => {
    // 不's pinyin-pro forms are bū / bú / bǔ / bù. A fact whose reading is a
    // tone-marked syllable outside that family (here xíng, the shape a future
    // chars.pinyin backfill could produce) must fail loud — never ship a
    // question whose answerIndex is -1.
    const mismatched = facts.map((f) =>
      f.char === '不' ? { ...f, reading: 'xíng' } : { ...f },
    );
    const badTier = buildTier(tier1.tier, mismatched);
    const levelIndex = badTier.levels.findIndex((level) =>
      level.some((f) => f.char === '不'),
    );
    expect(levelIndex).toBeGreaterThanOrEqual(0);
    expect(() => buildLevel(badTier, levelIndex + 1)).toThrow(
      /no tone option matches the reading of 不: "xíng" is not one of \[bū, bú, bǔ, bù\]/,
    );
  });
});
